mapper.select:
select



		,A.PROCESS_MODEL
		from RSK_INDIVID_CONDITION_VIEW  A


		from RSK_INDIVID_CONDITION A



	A.PRT_BAG_ID = #{prtBagId,jdbcType=VARCHAR}
	AND A.IND_ID = #{indId,jdbcType=VARCHAR}

mapper.delete:
delete from RSK_INDIVID_CONDITION
where PRT_BAG_ID = #{prtBagId,jdbcType=VARCHAR}
  and IND_ID = #{indId,jdbcType=VARCHAR}

delete from RSK_INDIVID_UNITE t1
where
		t1.UNITE_ID in (select distinct t2.UNITE_ID from RSK_INDIVID_UNITE t2
						where t2.PRT_BAG_ID = #{prtBagId,jdbcType=VARCHAR}
						  and t2.IND_ID = #{indId,jdbcType=VARCHAR}
	)

delete from RSK_INDIVID_ASSET_DEL
where PRT_BAG_ID = #{prtBagId,jdbcType=VARCHAR}
  and IND_ID = #{indId,jdbcType=VARCHAR}

delete from RSK_INDIVID_SPECIAL_STAGE
where PRT_BAG_ID = #{prtBagId,jdbcType=VARCHAR}
  and IND_ID = #{indId,jdbcType=VARCHAR}

mapper.select:
select
A.IND_ID id,
B.IND_NAME text
from RSK_PORTFOLIO_INDICATOR A
left join RSK_ISUP_INDICATOR B on A.IND_ID = B.IND_ID

	A.IND_ID != #{indId}
	and A.PORTFOLIO_ID = #{prtBagId}


		and A.IND_ID in ${initValue}



		and A.IND_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%'))

select
A.IND_ID id,
B.IND_NAME text
from RSK_RULE_INDICATOR A
left join RSK_ISUP_INDICATOR B on A.IND_ID = B.IND_ID

	A.IND_ID != #{indId}
	and A.RULE_ID = #{prtBagId}


		and A.IND_ID in ${initValue}



		and A.IND_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%'))

SELECT A.CONDITION_ITEM ID, A.CONDITION_NAME TEXT FROM RSK_INDIVID_CONDITION_CUSTOM A
AND (A.CONDITION_ITEM LIKE concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR A.CONDITION_NAME LIKE concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
and A.CONDITION_ITEM = #{initValue}

select DISTINCT m.PORTFOLIO_ID  FROM RSK_RULE_PORTFOLIO m where exists (
		select 1 from RSK_RULE_INDICATOR n where n.IND_ID = #{indId,jdbcType=VARCHAR} and m.RULE_ID=n.RULE_ID
	) and m.PORTFOLIO_ID =#{prtBagId,jdbcType=VARCHAR}
